function voiceBoard(){const board=ensureBrandPackage();board.voices=board.voices||[];return board}
const decorateBeforeVoices=decorateBrand;decorateBrand=function(){decorateBeforeVoices();if(currentPage!=='assets'||assetTab!=='brand')return;if(!document.querySelector('[data-brand-mode="voices"]')){const button=document.createElement('button');button.dataset.brandMode='voices';button.textContent='Brand voices';button.onclick=()=>renderBrandMode('voices');document.querySelector('.brand-editor-tabs').append(button)}};
const brandModeBeforeVoices=renderBrandMode;renderBrandMode=function(mode){if(mode!=='voices')return brandModeBeforeVoices(mode);if(!can('assets.manage')){toast('Manage asset groups permission required.');return}const board=voiceBoard();document.querySelectorAll('[data-brand-mode]').forEach(b=>b.classList.toggle('active',b.dataset.brandMode==='voices'));document.querySelector('#brand-editor-content').innerHTML=`<div class="asset-section-title"><div><h3>Brand voices</h3><p>Reusable voice profiles. Every profile inherits this Asset Group’s master do’s and don’ts.</p></div><button class="btn primary" id="create-brand-voice">＋ Create brand voice</button></div><div class="voice-cards">${board.voices.map(v=>`<article><h4>${safe(v.name)}</h4><span class="badge ${v.reviewed?'ok':'warn'}">${v.reviewed?'Human reviewed':'Needs review'}</span><p>${safe(v.voice)}</p><small class="ops-muted">Source: ${v.method==='website'?'Website reference · mock analysis':'Written brand description'}</small><div class="actions" style="margin-top:15px"><button class="btn" data-edit-voice="${v.id}">Edit & review</button><button class="btn" data-apply-voice="${v.id}" ${v.reviewed?'':'disabled'}>Use in guideline</button></div></article>`).join('')||'<div class="ops-empty"><h3>No voice profiles yet</h3><p>Create a voice from a website reference or a short description, then edit and review it.</p></div>'}</div>`;document.querySelector('#create-brand-voice').onclick=createBrandVoice;document.querySelectorAll('[data-edit-voice]').forEach(b=>b.onclick=()=>reviewBrandVoice(board.voices.find(v=>v.id===b.dataset.editVoice)));document.querySelectorAll('[data-apply-voice]').forEach(b=>b.onclick=()=>applyBrandVoice(board.voices.find(v=>v.id===b.dataset.applyVoice)))};
function createBrandVoice(){if(!can('assets.manage'))return;assetModal('Create Brand Voice',`<form id="create-voice-form"><p class="form-description">Use a website reference or describe your brand. Website analysis and drafting are simulated, with no external request.</p><div class="field"><label for="voice-profile-name">Brand Voice name *</label><input id="voice-profile-name" required maxlength="100" placeholder="e.g. Harbourview Community Voice"></div><h3>How would you like to create it?</h3><div class="voice-method-choice"><label><input type="radio" name="voice-method" value="website" checked>Import from website · mock</label><label><input type="radio" name="voice-method" value="description">Describe your brand</label></div><div class="field" id="voice-source-field"><label for="voice-source">Website URL *</label><input id="voice-source" type="url" required placeholder="https://harbourview.example"></div><div class="field"><label for="voice-context">Additional context (optional)</label><textarea id="voice-context" rows="5" maxlength="500" placeholder="Tell us about personality, audience or style…"></textarea><small id="voice-context-count">0 / 500</small></div><p id="voice-creation-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Continue · mock draft</button></div></form>`);document.querySelector('#voice-context').oninput=e=>document.querySelector('#voice-context-count').textContent=e.target.value.length+' / 500';document.querySelectorAll('[name="voice-method"]').forEach(r=>r.onchange=()=>{const website=document.querySelector('[name="voice-method"]:checked').value==='website';document.querySelector('#voice-source-field').innerHTML=website?'<label for="voice-source">Website URL *</label><input id="voice-source" type="url" required placeholder="https://harbourview.example">':'<label for="voice-source">Describe your brand *</label><textarea id="voice-source" rows="4" required maxlength="1500" placeholder="Who you serve, what you do, and how you want to sound…"></textarea>'});document.querySelector('#create-voice-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#voice-profile-name').value.trim(),method=document.querySelector('[name="voice-method"]:checked').value,source=document.querySelector('#voice-source').value.trim(),context=document.querySelector('#voice-context').value.trim();if(!name||!source)return;if(method==='website'){let parsed;try{parsed=new URL(source)}catch{document.querySelector('#voice-creation-error').textContent='Enter a valid HTTPS website URL.';return}if(parsed.protocol!=='https:'){document.querySelector('#voice-creation-error').textContent='Use an HTTPS website reference.';return}}const v={id:crypto.randomUUID(),name,method,source,context,voice:'Clear, approachable and respectful. Explain municipal services in plain language.',mood:'Calm, helpful and confident',tone:'Inclusive and practical',audience:'Residents and community members',reviewed:false,created:nowISO()};reviewBrandVoice(v,true)}}
function reviewBrandVoice(v,isNew=false){assetModal('Review Brand Voice',`<form id="review-voice-form"><p class="form-description">${v.method==='website'?'Mock analysis only: the website was not fetched.':'Mock draft from your description.'} Edit the proposed profile before saving.</p><div class="inherited-rules"><strong>Master guardrails always apply</strong><p>${safe(voiceBoard().master.dos)}</p><p>${safe(voiceBoard().master.donts)}</p></div>${[['name','Voice profile name'],['voice','Voice'],['mood','Mood'],['tone','Tone'],['audience','Audience']].map(([key,label])=>`<div class="field"><label for="voice-review-${key}">${label}</label><textarea id="voice-review-${key}" rows="${key==='voice'?3:2}" required>${safe(v[key]||'')}</textarea></div>`).join('')}<details><summary>Source and supplied context</summary><p class="ops-muted">${safe(v.source)}</p><p class="ops-muted">${safe(v.context)}</p></details><label class="preference-toggle"><input id="voice-review-confirm" type="checkbox" ${v.reviewed?'checked':''}>I reviewed this profile against the master direction.</label><div class="form-actions"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary" type="submit">Save voice profile</button></div></form>`);document.querySelector('#review-voice-form').onsubmit=e=>{e.preventDefault();for(const key of ['name','voice','mood','tone','audience'])v[key]=document.querySelector('#voice-review-'+key).value.trim();if(['name','voice','mood','tone','audience'].some(k=>!v[k]))return;v.reviewed=document.querySelector('#voice-review-confirm').checked;const board=voiceBoard();if(isNew)board.voices.push(v);else{const index=board.voices.findIndex(x=>x.id===v.id);board.voices[index]=v}logOps('Brand voice saved',v.name+'; '+(v.reviewed?'reviewed':'draft')+'; no external AI call.');close();renderBrandMode('voices');toast('Brand voice saved under this Asset Group.')}}
function applyBrandVoice(v){if(!v?.reviewed)return;const board=voiceBoard();assetModal('Use Brand Voice in guideline',`<form id="apply-voice-form"><p class="form-description">Apply ${safe(v.name)} to a guideline. Its visual references remain attached and it must be reviewed again.</p><div class="field"><label for="voice-target-set">Guideline set</label><select id="voice-target-set">${board.sets.map(s=>`<option value="${s.id}">${safe(s.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Apply voice</button></form>`);document.querySelector('#apply-voice-form').onsubmit=e=>{e.preventDefault();const set=board.sets.find(s=>s.id===document.querySelector('#voice-target-set').value);set.voice=v.voice;set.voiceProfileId=v.id;set.mood=v.mood;set.tone=v.tone;set.audience=v.audience;set.reviewed=false;board.selected=set.id;logOps('Brand voice applied to guideline',v.name+' → '+set.name+'; review required.');close();renderBrandMode('sets')}}
// Final navigation order requested by the user.
navSections.splice(0,navSections.length,
 ['ENGAGEMENT',[['soc','SOC','',null],['inbox','Inbox & Comments','','inbox.respond'],['listening','Social Listening','','reports.view']]],
 ['SOCIAL CHANNELS & CONTENT',[['channels','Social Channels','',null],['content','All Content','','content.create'],['calendar','Publishing Calendar','','content.publish'],['media','Media Storage','',null],['assets','Asset Groups','','assets.manage']]],
 ['ADVERTISING',[['ads','Campaigns · planned','','ads.create']]],
 ['INSIGHTS',[['analytics','Analytics & Reports','','reports.view']]],
 ['SETTINGS',[['users','Users & Access','','admin'],['audit','Activity Log','','admin'],['preferences','My Preferences','',null]]]
);
const mediaScreenBeforeIntegrationFix=showMediaStorage;showMediaStorage=function(){mediaScreenBeforeIntegrationFix();document.querySelector('#media-mock-integrations').onclick=()=>{assetModal('Media integrations · mocked','<p class="form-description">No real service will be contacted.</p><div class="actions"><button class="btn" id="mock-canva-connect">Mock Connect Canva</button><button class="btn" id="mock-drive-connect">Mock Connect Drive</button></div><p id="mock-media-connection-result" class="ops-muted">No integration connected.</p>');document.querySelector('#mock-canva-connect').onclick=()=>document.querySelector('#mock-media-connection-result').textContent='Canva connection simulated. No authentication or external request.';document.querySelector('#mock-drive-connect').onclick=()=>document.querySelector('#mock-media-connection-result').textContent='Drive connection simulated. No authentication or external request.'}};
renderWorkspace('media');
